import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:shared_preferences/shared_preferences.dart';
import 'package:the_only/core/data/persistent_library.dart';
import 'package:the_only/main.dart';
void main(){testWidgets('renders unified shell with functional local sixth-section gate',(tester) async {SharedPreferences.setMockInitialValues({});final store=PersistentLibraryStore(await SharedPreferences.getInstance());await store.initialize();await tester.pumpWidget(TheOnlyApp(store:store));await tester.pumpAndSettle();expect(find.byType(TheOnlyShell),findsOneWidget);expect(Directionality.of(tester.element(find.byType(TheOnlyShell))),TextDirection.rtl);expect(find.text('السينما'),findsWidgets);expect(find.text('البث المباشر'),findsOneWidget);expect(find.text('المصادر'),findsOneWidget);expect(find.text('المحللات'),findsOneWidget);expect(find.text('المزودون'),findsOneWidget);expect(find.text('تشخيص النظام'),findsNothing);await tester.tap(find.byKey(const Key('settings-button')));await tester.pumpAndSettle();expect(find.byKey(const Key('section-optional')),findsOneWidget);await tester.tap(find.byKey(const Key('section-optional')));await tester.pumpAndSettle();await tester.pageBack();await tester.pumpAndSettle();expect(find.text('تشخيص النظام'),findsWidgets);await tester.tap(find.text('تشخيص النظام').last);await tester.pumpAndSettle();expect(find.byKey(const Key('system-diagnostics-screen')),findsOneWidget);expect(find.text('معلومات الجهاز المحلية فقط. لا يتم رفع أي بيانات تشخيصية.'),findsOneWidget);});}
